  tool?: "sports";
}>;
  // Get time for the given UTC offsets.
  time?: Array<{
  // UTC offset formatted like "+03:00".
  utc_offset: string;
}>;
  // Look up weather forecasts.
  weather?: Array<{
  // Number of days to return. Defaults to 7.
  duration?: number;
